glsl:
vec4 effect(vec2 uv) {
  vec4 c = getColor(uv);
  vec2 sp = vec2(0.72 + 0.06 * sin(uTime * 0.6), 0.78);
  vec2 d = uv - sp; d.x *= uRatio;
  vec3 flare = vec3(1.0, 0.85, 0.6) * (0.02 / (length(d) + 0.02));
  flare += vec3(1.0, 0.8, 0.5) * pow(max(0.0, 1.0 - abs(d.y) * 40.0), 2.0) * 0.25;
  for (int i = 1; i <= 3; i++) {
    vec2 g = sp + (vec2(0.5) - sp) * float(i) * 0.55;
    vec2 dg = uv - g; dg.x *= uRatio;
    flare += vec3(0.3, 0.6, 1.0) * smoothstep(0.05 + 0.02 * float(i), 0.0, length(dg)) * 0.35;
  }
  return vec4(c.rgb + flare * uAmount, c.a);
}
